import attr

from taf.ul.ue.sim.env_setup.devices.iphy_airphone_interface import (
    IphyAirphoneInterface,
)


@attr.s(cmp=False, hash=True)
class AirPhone(IphyAirphoneInterface):
    def _get_lmp_password(self) -> str:
        return self.configuration.l1.common_units[0].lmp_connection.password

    def _get_lmp_ip_for_ute(self):
        """Not used, it's here only due to ABC, must be removed after migration to TAF schema."""
        # todo remove

    def _get_lmp_ip_for_taf(self) -> str:
        return self.configuration.l1.common_units[0].lmp_connection.addr

    def _get_taf_pdu_config(self):
        return self.configuration.l1.common_units[0].pdu_port

    def _set_vlan(self):
        with self.open_rmods_xml(self.sim_xml_path) as config_xml:
            all_optlinks = config_xml.findall(".//optlink")
            for identity in all_optlinks:
                if (preferred_vlan_id := identity.find("preferredVlanId")) is not None:
                    preferred_vlan_id.text = str(self.configuration.preferred_vlans[0].preferred_vlan_id)
                else:
                    self.logger.debug("preferredVlanId not found.")
